(() => {
const data=[
{name:'Condomínio Solar',city:'Belo Horizonte / MG',owner:'João da Silva',score:92,visit:'Hoje · 09:00',status:'healthy'},
{name:'Residencial Park',city:'Belo Horizonte / MG',owner:'Carla Mendes',score:76,visit:'Hoje · 14:00',status:'attention'},
{name:'Edifício das Palmeiras',city:'Nova Lima / MG',owner:'João da Silva',score:84,visit:'Hoje · 16:30',status:'healthy'},
{name:'Residencial Central',city:'Contagem / MG',owner:'Bruno Costa',score:58,visit:'28 ago · 10:00',status:'critical'},
{name:'Condomínio Village',city:'Betim / MG',owner:'Carla Mendes',score:88,visit:'29 ago · 09:30',status:'healthy'},
{name:'Edifício Itália',city:'Belo Horizonte / MG',owner:'Bruno Costa',score:69,visit:'30 ago · 11:00',status:'attention'}];
const labels={healthy:'Saudável',attention:'Atenção',critical:'Crítico'},rows=document.querySelector('[data-rows]'),search=document.querySelector('[data-search]'),status=document.querySelector('[data-status]');let sort='name',ascending=true;
const render=()=>{const query=search.value.trim().toLocaleLowerCase('pt-BR'),filtered=data.filter(item=>(status.value==='all'||item.status===status.value)&&[item.name,item.city,item.owner].some(value=>value.toLocaleLowerCase('pt-BR').includes(query))).sort((a,b)=>{const result=sort==='score'?a.score-b.score:a.name.localeCompare(b.name,'pt-BR');return ascending?result:-result});rows.innerHTML=filtered.map((item,index)=>`<tr><td data-label="Condomínio"><button class="condo-link" data-index="${data.indexOf(item)}">${item.name}</button></td><td data-label="Localização">${item.city}</td><td data-label="Responsável">${item.owner}</td><td data-label="Saúde"><span class="score"><i style="--score:${item.score}%"></i>${item.score}/100</span></td><td data-label="Próxima visita">${item.visit}</td><td data-label="Status"><span class="state ${item.status}">${labels[item.status]}</span></td><td><button class="ms-icon-button" data-index="${data.indexOf(item)}" aria-label="Ver ${item.name}">›</button></td></tr>`).join('');document.querySelector('[data-count]').textContent=`${filtered.length} ${filtered.length===1?'resultado':'resultados'}`;document.querySelector('[data-empty]').hidden=filtered.length>0;document.querySelector('.table-wrap').hidden=filtered.length===0;};
const open=index=>{const item=data[index],dialog=document.querySelector('[data-detail]');dialog.querySelector('[data-detail-name]').textContent=item.name;dialog.querySelector('[data-detail-score]').textContent=`${item.score}/100 · ${labels[item.status]}`;dialog.querySelector('[data-detail-owner]').textContent=item.owner;dialog.querySelector('[data-detail-visit]').textContent=item.visit;dialog.showModal();};
[search,status].forEach(control=>control.addEventListener('input',render));document.querySelectorAll('[data-clear]').forEach(button=>button.addEventListener('click',()=>{search.value='';status.value='all';render();search.focus()}));document.querySelectorAll('[data-sort]').forEach(button=>button.addEventListener('click',()=>{ascending=sort===button.dataset.sort?!ascending:true;sort=button.dataset.sort;render()}));rows.addEventListener('click',event=>{const button=event.target.closest('[data-index]');if(button)open(Number(button.dataset.index))});document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>document.querySelector('[data-detail]').close()));document.querySelector('[data-new]').addEventListener('click',()=>{const toast=document.querySelector('[data-toast]');toast.textContent='Cadastro demonstrativo: integração pendente de aprovação.';toast.classList.add('is-visible');setTimeout(()=>toast.classList.remove('is-visible'),2800)});render();
})();
